    public static bool TestConstructorFailureCode(byte[]? bytes, int part)
    {
        if ((uint)part >= (uint)ConstructorFailureShapes.Length || bytes is null)
            return false;
        var shape = ConstructorFailureShapes[part];
        if (bytes.Length != shape.Hex.Length / 2)
            return false;
        byte[] normalized = [.. bytes];
        foreach (var field in shape.Fields)
            normalized.AsSpan(field.Field, 4).Clear();
        return normalized.AsSpan().SequenceEqual(Convert.FromHexString(shape.Hex));
    }

    public static bool TestConstructorFailureEhTable(byte[]? bytes, int part, ulong exceptionType, ulong wrapperType)
    {
        byte[] prefix = part switch
        {
            0 => [2, 26, 128, 70],
            1 => [2, 22, 72, 80],
            _ => []
        };
        ulong type = part == 0 ? exceptionType : wrapperType;
        return prefix.Length == 4 && bytes is { Length: 8 } && exceptionType is > 0 and <= uint.MaxValue && wrapperType is > 0 and <= uint.MaxValue && exceptionType != wrapperType && bytes.AsSpan(0, 4).SequenceEqual(prefix) && BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(4)) == type;
    }

    public static bool TestConstructorFailureUnwindBytes(byte[]? bytes, int part, ulong table)
    {
        byte[] prefix = part switch
        {
            0 => [1, 6, 3, 0, 6, 66, 2, 48, 1, 96, 0],
            1 => [1, 5, 2, 0, 5, 50, 1, 48, 0],
            2 => [1, 4, 1, 0, 4, 66, 0],
            3 => [1, 8, 2, 0, 8, 242, 1, 48, 0],
            4 => [1, 5, 2, 0, 5, 50, 1, 80, 4],
            5 => [1, 4, 1, 0, 4, 66, 1],
            6 => [1, 6, 3, 0, 6, 66, 2, 48, 1, 80, 4],
            _ => []
        };
        bool eh = part is 4 or 6;
        return prefix.Length != 0 && bytes is not null && bytes.Length == prefix.Length + (eh ? 4 : 0) && bytes.AsSpan(0, prefix.Length).SequenceEqual(prefix) && (!eh || table is > 0 and <= uint.MaxValue && BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(prefix.Length)) == table);
    }
